413	      await cubit.load();
414	
415	      final state = cubit.state as ResourceError<String>;
416	      expect(state.failure, isA<MalformedResponse>());
417	    });
418	
419	    test('a non-retryable VALIDATION_ERROR maps through the real Failure.'
420	        'fromCode pipeline to ResourceError — exactly one request left, no '
421	        'RetryInterceptor retry', () async {
422	      adapter.queueErrorResponse('VALIDATION_ERROR', 'period inválido');
423	
424	      final cubit = sl<DashboardNarrativeCubit>();
425	      await cubit.load();
